INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('草铵膦', '{"component":"草铵膦","ph":"5.0-6.0（弱酸性）","contraindications":"【作物限制】接触绿色部位即杀，需定向喷雾\n【混配限制】不建议与其他农药肥料混用"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('赤霉酸', '{"component":"赤霉酸","ph":"3.0-4.0（强酸性）","contraindications":"【作物限制】无明显作物限制\n【混配限制】不可与碱性农药混用；不可与含钙肥料混用（会沉淀失效）"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('苄氨基嘌呤', '{"component":"苄氨基嘌呤","ph":"5.5-6.5（弱酸性）","contraindications":"【作物限制】无明显作物限制\n【混配限制】不可与碱性农药混用"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('乙烯利', '{"component":"乙烯利","ph":"2.5-3.0（强酸性）","contraindications":"【作物限制】瓜类苗期禁用；弱小植株慎用\n【混配限制】不可与碱性农药混用；强酸性，与多数肥料需间隔使用"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('多效唑', '{"component":"多效唑","ph":"6.0-7.0（中性）","contraindications":"【作物限制】弱小植株慎用；残留期长，下茬作物注意\n【混配限制】不可与碱性农药混用"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('矮壮素', '{"component":"矮壮素","ph":"4.5-5.5（酸性）","contraindications":"【作物限制】弱小植株慎用\n【混配限制】不可与碱性农药混用"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('甲哌鎓', '{"component":"甲哌鎓","ph":"5.0-6.0（弱酸性）","contraindications":"【作物限制】无明显作物限制\n【混配限制】不可与碱性农药混用"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('芸苔素内酯', '{"component":"芸苔素内酯","ph":"5.5-6.5（弱酸性）","contraindications":"【作物限制】无明显作物限制\n【混配限制】不可与碱性农药混用；不可与除草剂混用"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('S-诱抗素', '{"component":"S-诱抗素","ph":"5.0-6.0（弱酸性）","contraindications":"【作物限制】无明显作物限制\n【混配限制】不可与碱性农药混用"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('氯吡脲', '{"component":"氯吡脲","ph":"6.0-7.0（中性）","contraindications":"【作物限制】瓜类需严格控制浓度；葡萄某些品种敏感\n【混配限制】不可与碱性农药混用"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('磷酸二氢钾', '{"component":"磷酸二氢钾","ph":"4.5-4.8（酸性）","contraindications":"【作物限制】无明显作物限制\n【混配限制】不可与含钙肥料（硝酸钙、氯化钙）混用，会生成磷酸钙沉淀；不可与含锰、含锌微量元素肥料混用"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('硝酸钙', '{"component":"硝酸钙","ph":"5.5-6.5（弱酸性）","contraindications":"【作物限制】无明显作物限制\n【混配限制】不可与含磷肥料（磷酸二氢钾）混用；不可与含硫酸根肥料混用"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('硼酸', '{"component":"硼酸","ph":"5.0-5.5（弱酸性）","contraindications":"【作物限制】无明显作物限制\n【混配限制】一般可混，但不可过量使用"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('硫酸锌', '{"component":"硫酸锌","ph":"5.0-5.5（弱酸性）","contraindications":"【作物限制】无明显作物限制\n【混配限制】不可与含磷肥料混用（生成磷酸锌沉淀）"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('腐殖酸', '{"component":"腐殖酸","ph":"9.0-10.0（碱性）","contraindications":"【作物限制】无明显作物限制\n【混配限制】不可与含钙肥料混用（产生絮凝沉淀）；不可与酸性农药混用"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('氨基酸', '{"component":"氨基酸","ph":"5.0-6.0（弱酸性）","contraindications":"【作物限制】无明显作物限制\n【混配限制】一般可混，但不可与强碱性农药混用"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('尿素', '{"component":"尿素","ph":"7.0-8.0（中性偏碱）","contraindications":"【作物限制】无明显作物限制\n【混配限制】一般可混，但高浓度时注意缩二脲危害"}', '2026-08-22T01:14:46.869Z');
